4. Numerical Computation: Rigorous Dedekind Cut Interval Arithmetic
Below are multi-language implementations of Dedekind Cut Interval Arithmetic, representing real numbers as enclosing bounds that guarantee inclusion:

Python 3C++20JuliaModern FortranMATLAB / OctaveLean 4


class IntervalReal:
    """Rigorous Real Number via Interval Arithmetic."""
    def __init__(self, lower: float, upper: float):
        assert lower &lt;= upper
        self.lo = float(lower)
        self.hi = float(upper)

    def __repr__(self):
        return f"[{self.lo:.8f}, {self.hi:.8f}]"

def sqrt_dedekind(target: float, tol: float = 1e-12) -&gt; IntervalReal:
    lo, hi = 0.0, max(1.0, float(target))
    while hi - lo &gt; tol:
        mid = (lo + hi) / 2.0
        if mid * mid &lt; target:
            lo = mid
        else:
            hi = mid
    return IntervalReal(lo, hi)

res = sqrt_dedekind(2.0)
print(f"Python 3: sqrt(2) in {res}")


#include &lt;iostream&gt;
#include &lt;iomanip&gt;
#include &lt;algorithm&gt;

struct IntervalReal {
    double lo, hi;
};

IntervalReal sqrt_dedekind(double target, double tol = 1e-12) {
    double lo = 0.0, hi = std::max(1.0, target);
    while (hi - lo &gt; tol) {
        double mid = (lo + hi) / 2.0;
        if (mid * mid &lt; target) lo = mid;
        else hi = mid;
    }
    return {lo, hi};
}

int main() {
    auto res = sqrt_dedekind(2.0);
    std::cout &lt;&lt; std::fixed &lt;&lt; std::setprecision(8);
    std::cout &lt;&lt; "C++20:    sqrt(2) in [" &lt;&lt; res.lo &lt;&lt; ", " &lt;&lt; res.hi &lt;&lt; "]\n";
    return 0;
}


struct IntervalReal
    lo::Float64
    hi::Float64
end

function sqrt_dedekind(target::Float64, tol::Float64 = 1e-12)::IntervalReal
    lo = 0.0
    hi = max(1.0, target)
    while hi - lo &gt; tol
        mid = (lo + hi) / 2.0
        if mid^2 &lt; target
            lo = mid
        else
            hi = mid
        end
    end
    return IntervalReal(lo, hi)
end

res = sqrt_dedekind(2.0)
println("Julia:    sqrt(2) in [$(res.lo), $(res.hi)]")


program dedekind_sqrt
  implicit none
  real(8) :: target, lo, hi, mid, tol
  target = 2.0d0
  tol = 1.0d-12
  lo = 0.0d0
  hi = max(1.0d0, target)

  do while ((hi - lo) &gt; tol)
    mid = (lo + hi) / 2.0d0
    if (mid * mid &lt; target) then
      lo = mid
    else
      hi = mid
    end if
  end do

  print '(A,F10.8,A,F10.8,A)', "Fortran:  sqrt(2) in [", lo, ", ", hi, "]"
end program dedekind_sqrt


