-- Lean 4: Dedekind Cuts and the Least Upper Bound Property in Mathlib
import Mathlib.Data.Real.Basic
import Mathlib.Order.Bounds.Basic

-- A Dedekind cut in Q
structure DedekindCut where
  carrier : Set ℚ
  nonempty : carrier.Nonempty
  non_univ : carrier ≠ Set.univ
  downward_closed : ∀ {p q : ℚ}, p &lt; q → q ∈ carrier → p ∈ carrier
  no_greatest : ∀ p ∈ carrier, ∃ q ∈ carrier, p &lt; q

-- Formalized Completeness of ℝ: Least Upper Bound Property
theorem real_complete_lub (S : Set ℝ) (hne : S.Nonempty) (hbd : BddAbove S) :
    ∃ x : ℝ, IsLUB S x := by
  exact ⟨sSup S, isLUB_csSup hne hbd⟩

