import numpy as np

def picard_step(f, t_grid, x_prev, x0):
    x_new = np.zeros_like(x_prev)
    x_new[0] = x0
    for i in range(1, len(t_grid)):
        s = t_grid[:i+1]
        x_new[i] = x0 + np.trapz(f(s, x_prev[:i+1]), s)
    return x_new

# dx/dt = x, x(0) = 1 =&gt; Exact: exp(t)
t = np.linspace(0.0, 1.0, 50)
x = np.ones_like(t) # x0(t) = 1
for _ in range(4):
    x = picard_step(lambda s, v: v, t, x, 1.0)
print(f"Python 3: Picard Iteration 4 at t=1: {x[-1]:.6f} (True: {np.exp(1):.6f})")


#include &lt;iostream&gt;
#include &lt;vector&gt;
#include &lt;cmath&gt;
#include &lt;iomanip&gt;

int main() {
    int n = 50;
    double t_end = 1.0, dt = t_end / (n - 1);
    std::vector&lt;double&gt; t(n), x(n, 1.0);
    for (int i = 0; i &lt; n; ++i) t[i] = i * dt;

    for (int iter = 0; iter &lt; 4; ++iter) {
        std::vector&lt;double&gt; x_new(n, 1.0);
        for (int i = 1; i &lt; n; ++i) {
            double trap = 0.0;
            for (int j = 0; j &lt; i; ++j) {
                trap += 0.5 * (x[j] + x[j+1]) * dt;
            }
            x_new[i] = 1.0 + trap;
        }
        x = x_new;
    }
    std::cout &lt;&lt; std::fixed &lt;&lt; std::setprecision(6);
    std::cout &lt;&lt; "C++20:    Picard Iteration 4 at t=1: " &lt;&lt; x.back() &lt;&lt; "\n";
    return 0;
}


n = 50
t = range(0.0, 1.0, length=n)
dt = step(t)
x = ones(n)

for _ in 1:4
    x_new = ones(n)
    for i in 2:n
        trap = sum(0.5 * (x[j] + x[j+1]) * dt for j in 1:i-1)
        x_new[i] = 1.0 + trap
    end
    global x = x_new
end

println("Julia:    Picard Iteration 4 at t=1: $(round(x[end], digits=6))")


program picard
  implicit none
  integer, parameter :: n = 50
  integer :: iter, i, j
  real(8) :: dt, trap
  real(8) :: x(n), x_new(n)

  dt = 1.0d0 / (n - 1)
  x = 1.0d0

  do iter = 1, 4
    x_new(1) = 1.0d0
    do i = 2, n
      trap = 0.0d0
      do j = 1, i - 1
        trap = trap + 0.5d0 * (x(j) + x(j+1)) * dt
      end do
      x_new(i) = 1.0d0 + trap
    end do
    x = x_new
  end do

  print '(A,F10.6)', "Fortran:  Picard Iteration 4 at t=1: ", x(n)
end program picard


