import numpy as np

def sphere_volume_mc(r: float = 1.0, n_samples: int = 100000) -&gt; float:
    pts = np.random.uniform(-r, r, size=(n_samples, 3))
    inside = np.sum(pts**2, axis=1) &lt;= r**2
    return float((2.0 * r)**3 * np.mean(inside))

vol = sphere_volume_mc(1.0)
print(f"Python 3: Unit Sphere Volume = {vol:.4f} (True: {4/3*np.pi:.4f})")


#include &lt;iostream&gt;
#include &lt;random&gt;

int main() {
    std::mt19937_64 rng(42);
    std::uniform_real_distribution&lt;double&gt; dist(-1.0, 1.0);
    int n = 100000, count = 0;

    for (int i = 0; i &lt; n; ++i) {
        double x = dist(rng), y = dist(rng), z = dist(rng);
        if (x*x + y*y + z*z &lt;= 1.0) count++;
    }
    double vol = 8.0 * (static_cast&lt;double&gt;(count) / n);
    std::cout &lt;&lt; "C++20:    Unit Sphere Volume = " &lt;&lt; vol &lt;&lt; "\n";
    return 0;
}


