-- Lean 4: Fubini-Tonelli Product Integration
import Mathlib.MeasureTheory.Integral.Prod
import Mathlib.MeasureTheory.Measure.Lebesgue.Basic

open MeasureTheory

-- Formal statement of Fubini's Theorem for integrable functions on product spaces
theorem fubini_theorem {α β : Type*} [MeasurableSpace α] [MeasurableSpace β]
    (μ : Measure α) (ν : Measure β) [SigmaFinite μ] [SigmaFinite ν]
    (f : α × β → ℝ) (hf : Integrable f (μ.prod ν)) :
    ∫ p, f p ∂(μ.prod ν) = ∫ x, (∫ y, f (x, y) ∂ν) ∂μ :=
  integral_prod f hf

2. Numerical Computation: Curve Reconstruction from Curvature

Python 3C++20JuliaModern FortranMATLAB / OctaveLean 4


import numpy as np

def reconstruct_curve_2d(kappa_fn, s_max: float = 3.0, n: int = 1000):
    s = np.linspace(0.0, s_max, n)
    ds = s[1] - s[0]
    theta = np.cumsum([kappa_fn(si) for si in s]) * ds
    x = np.cumsum(np.cos(theta)) * ds
    y = np.cumsum(np.sin(theta)) * ds
    return x[-1], y[-1]

# Euler spiral / clothoid: kappa(s) = 2*s
xf, yf = reconstruct_curve_2d(lambda s: 2.0 * s, 3.0)
print(f"Python 3: Clothoid End at s=3.0: x = {xf:.4f}, y = {yf:.4f}")


#include &lt;iostream&gt;
#include &lt;cmath&gt;
#include &lt;iomanip&gt;

int main() {
    int n = 1000;
    double s_max = 3.0, ds = s_max / n;
    double theta = 0.0, x = 0.0, y = 0.0;

    for (int i = 0; i &lt; n; ++i) {
        double s = i * ds;
        double kappa = 2.0 * s;
        theta += kappa * ds;
        x += std::cos(theta) * ds;
        y += std::sin(theta) * ds;
    }
    std::cout &lt;&lt; std::fixed &lt;&lt; std::setprecision(4);
    std::cout &lt;&lt; "C++20:    Clothoid End at s=3.0: x = " &lt;&lt; x &lt;&lt; ", y = " &lt;&lt; y &lt;&lt; "\n";
    return 0;
}


