import numpy as np

def erf_cf(z: float, max_terms: int = 50) -&gt; float:
    tiny = 1e-30
    f = z if z != 0 else tiny
    C = f; D = 0.0
    for m in range(1, max_terms + 1):
        a_m = m / 2.0; b_m = z
        D = b_m + a_m * D
        if abs(D) &lt; tiny: D = tiny
        C = b_m + a_m / C
        if abs(C) &lt; tiny: C = tiny
        D = 1.0 / D
        delta = C * D
        f *= delta
        if abs(delta - 1.0) &lt; 1e-15: break
    return 1.0 - (np.exp(-z**2) / np.sqrt(np.pi)) * (1.0 / f)

