struct Node : std::enable_shared_from_this&lt;Node&gt; {
    double value;
    double grad = 0.0;
    std::vector&lt;std::shared_ptr&lt;Node&gt;&gt; parents;
    std::vector&lt;std::function&lt;double(double)&gt;&gt; vjps;

    Node(double v) : value(v) {}
    Node(double v, std::vector&lt;std::shared_ptr&lt;Node&gt;&gt; p, std::vector&lt;std::function&lt;double(double)&gt;&gt; f)
        : value(v), parents(p), vjps(f) {}

    void backward(double upstream = 1.0) {
        grad += upstream;
        for (size_t i = 0; i &lt; parents.size(); ++i) {
            parents[i]-&gt;backward(vjps[i](upstream));
        }
    }
};

int main() {
