        std::vector{x1, x2}, 
        std::vector&lt;std::function&lt;double(double)&gt;&gt;{[](double g){return g;}, [](double g){return g;}});
    auto y = std::make_shared&lt;Node&gt;(s-&gt;value * x1-&gt;value,
        std::vector{s, x1},
        std::vector&lt;std::function&lt;double(double)&gt;&gt;{[x1](double g){return g * x1-&gt;value;}, [s](double g){return g * s-&gt;value;}});

    y-&gt;backward(1.0);
    std::cout &lt;&lt; "C++20:    y = " &lt;&lt; y-&gt;value &lt;&lt; ", dy/dx1 = " &lt;&lt; x1-&gt;grad &lt;&lt; ", dy/dx2 = " &lt;&lt; x2-&gt;grad &lt;&lt; "\n";
    return 0;
}


mutable struct Node
    value::Float64
    grad::Float64
    parents::Vector{Node}
    vjps::Vector{Function}
    Node(v) = new(v, 0.0, Node[], Function[])
    Node(v, p, f) = new(v, 0.0, p, f)
end

function backward!(node::Node, upstream::Float64 = 1.0)
    node.grad += upstream
    for (parent, vjp) in zip(node.parents, node.vjps)
        backward!(parent, vjp(upstream))
    end
end

