int main() {
    int n = 1000;
    double t0 = 0.0, t1 = 2.0 * M_PI;
    double dt = (t1 - t0) / n;
    double length = 0.0;

    auto x = [](double t){ return std::cos(t); };
    auto y = [](double t){ return std::sin(t); };
    auto z = [](double t){ return t; };

    for (int i = 0; i &lt; n; ++i) {
        double ta = t0 + i * dt, tb = ta + dt;
        double dx = x(tb) - x(ta);
        double dy = y(tb) - y(ta);
        double dz = z(tb) - z(ta);
        length += std::sqrt(dx*dx + dy*dy + dz*dz);
    }
    std::cout &lt;&lt; std::fixed &lt;&lt; std::setprecision(6);
    std::cout &lt;&lt; "C++20:    Length = " &lt;&lt; length &lt;&lt; "\n";
    return 0;
}


